360		seedDoc(t, h, "doc1", 1)
361	
362		done := make(chan map[string]any, 1)
363		go func() {
364			w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc1/changes/poll?after=1&waitMs=30000")
365			if w.Code != http.StatusOK {
366				t.Errorf("poll status = %d body = %s", w.Code, w.Body.String())
367			}
368			done <- body
369		}()
370	
371		// Give the poll a moment to park, then commit through the session.
372		time.Sleep(50 * time.Millisecond)
373		w, _ := postSessionChanges(t, h, "sess", "doc1", `{"changes":[{"id":"live","payload":{"n":2}}]}`)
374		if w.Code != http.StatusOK {
375			t.Fatal(w.Body.String())
376		}
377	
378		select {
379		case body := <-done:
380			rows := body["changes"].([]any)
381			if len(rows) != 1 || rows[0].(map[string]any)["id"] != "live" {
382				t.Fatalf("polled rows = %v", rows)
383			}
384			row := rows[0].(map[string]any)
385			if row["deviceId"] != "dev" || row["cursor"].(float64) != 2 {
386				t.Fatalf("polled row = %v", row)
387			}
388			if body["timedOut"] != false {
389				t.Fatalf("poll timed out despite the commit: %v", body)
390			}
391		case <-time.After(5 * time.Second):
392			t.Fatal("session commit did not wake the parked poll")
393		}
394	}
