250			{"empty document segment", http.MethodGet, "/v1/sessions/sess/documents//crdt/state"},
251			{"trailing slash", http.MethodGet, sessionCRDTStatePath("sess", "doc") + "/"},
252			{"extra segment", http.MethodGet, sessionCRDTStatePath("sess", "doc") + "/extra"},
253			{"bare crdt namespace", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt"},
254			{"crdt namespace with slash", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt/"},
255			{"missing state word", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt/other"},
256		}
257		for _, tc := range cases {
258			t.Run(tc.name, func(t *testing.T) {
259				rec := httptest.NewRecorder()
260				h.ServeHTTP(rec, httptest.NewRequest(tc.method, tc.path, nil))
261				assertJSONErrorStatus(t, rec, http.StatusBadRequest)
262			})
263		}
264	
265		// Shape beats every later judgment: the same malformed shapes against an
266		// unknown session and a revoked document are still 400, not 404/403.
267		order := []struct {
268			name   string
269			method string
270			path   string
271		}{
272			{"wrong method, unknown session", http.MethodPost, sessionCRDTStatePath("ghost", "doc")},
273			{"extra segment, unknown session", http.MethodGet, sessionCRDTStatePath("ghost", "doc") + "/extra"},
274			{"empty session before lookup", http.MethodGet, "/v1/sessions//documents/doc/crdt/state"},
275			{"wrong method despite revocation", http.MethodPost, sessionCRDTStatePath("sess", "doc2")},
276		}
277		for _, tc := range order {
278			t.Run(tc.name, func(t *testing.T) {
279				rec := httptest.NewRecorder()
280				h.ServeHTTP(rec, httptest.NewRequest(tc.method, tc.path, nil))
281				assertJSONErrorStatus(t, rec, http.StatusBadRequest)
282			})
283		}
284	}
285	
286	// The read is read-only: it creates no CRDT state, advances no change cursor
287	// and leaves no change record.
288	func TestSessionCRDTStateIsReadOnly(t *testing.T) {
289		h, _ := newTestHandler(t)
290		createSessionViaHTTP(t, h, "dev-1", "sess")
291	
292		for i := 0; i < 3; i++ {
293			rec := httptest.NewRecorder()
294			h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, sessionCRDTStatePath("sess", "doc"), nil))
295			assertJSONErrorStatus(t, rec, http.StatusNotFound)
296		}
297		// The document-level read agrees that the reads created no state.
298		rec := httptest.NewRecorder()
299		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/v1/documents/doc/crdt/state", nil))
300		assertJSONErrorStatus(t, rec, http.StatusNotFound)
301	
302		// Seed CRDT state and a change, then read repeatedly; the change page and
303		// its cursor are untouched.
304		w, _ := postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev-1",
305			crdtCounterOp("a1", 2)))
306		if w.Code != http.StatusOK {
307			t.Fatal(w.Body.String())
308		}
309		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
310			"deviceId": "dev-1",
311			"changes":  []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
312		})
313		if w.Code != http.StatusOK {
314			t.Fatal(w.Body.String())
315		}
316		for i := 0; i < 3; i++ {
317			r := httptest.NewRecorder()
318			h.ServeHTTP(r, httptest.NewRequest(http.MethodGet, sessionCRDTStatePath("sess", "doc"), nil))
319			if r.Code != http.StatusOK || r.Body.String() != `{"type":"counter","value":2}`+"\n" {
320				t.Fatalf("read %d = %d %q", i, r.Code, r.Body.String())
321			}
322		}
323		page := httptest.NewRecorder()
324		h.ServeHTTP(page, httptest.NewRequest(http.MethodGet, "/v1/documents/doc/changes", nil))
325		var body struct {
326			Changes    []json.RawMessage `json:"changes"`
327			NextCursor int64             `json:"nextCursor"`
328		}
329		if err := json.Unmarshal(page.Body.Bytes(), &body); err != nil {
330			t.Fatal(page.Body.String())
331		}
332		if len(body.Changes) != 1 || body.NextCursor != 1 {
333			t.Fatalf("changes page mutated by reads: %s", page.Body.String())
334		}
335	}
336	
337	// Over real connections the session read, the document read and the
338	// subscription push all carry byte-identical state at the same instant.
339	func TestSessionCRDTStateMatchesDocumentReadAndPush(t *testing.T) {
340		srv, _ := newWSTestServer(t)
341		setupSession(t, srv, "dev-1", "sess", "doc", 0)
342		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 9))); code != http.StatusOK {
343			t.Fatalf("submit = %d", code)
344		}
345	
346		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
347		if hs.StatusCode != http.StatusSwitchingProtocols {
348			t.Fatalf("upgrade = %d", hs.StatusCode)
349		}
350		defer conn.close()
351		frame := conn.readCRDTRaw()
352	
353		sessionBody := mustReadBody(t, srv, sessionCRDTStatePath("sess", "doc"))
354		documentBody := mustReadBody(t, srv, "/v1/documents/doc/crdt/state")
355		if string(frame) != sessionBody || sessionBody != documentBody {
356			t.Fatalf("frame=%q session=%q document=%q", frame, sessionBody, documentBody)
357		}
358	}
359	
360	// Identifiers literally named "state"/"crdt" stay ordinary identifiers on the
361	// session state read path.
362	func TestSessionCRDTStateKeywordIdentifiers(t *testing.T) {
363		h, _ := newTestHandler(t)
364		createSessionViaHTTP(t, h, "dev-1", "state")
365		w, _ := postJSON(t, h, "/v1/documents/crdt/crdt/ops", crdtCounterBody("dev-1",
366			crdtCounterOp("a1", 4)))
367		if w.Code != http.StatusOK {
368			t.Fatalf("submit to doc crdt: %d %s", w.Code, w.Body.String())
369		}
370	
371		rec := httptest.NewRecorder()
372		h.ServeHTTP(rec, httptest.NewRequest(http.MethodGet,
373			"/v1/sessions/state/documents/crdt/crdt/state", nil))
374		if rec.Code != http.StatusOK {
375			t.Fatalf("status = %d %s", rec.Code, rec.Body.String())
376		}
377		if rec.Body.String() != `{"type":"counter","value":4}`+"\n" {
378			t.Fatalf("body = %q", rec.Body.String())
379		}
380	}
381	
382	// After a process restart the session read answers the same state, 404s and
383	// 403s as before; the read itself persists nothing.
384	func TestSessionCRDTStateConsistentAcrossRestart(t *testing.T) {
385		path := filepath.Join(t.TempDir(), "session-crdt.db")
386	
387		s1, err := app.Open(path)
388		if err != nil {
389			t.Fatal(err)
390		}
391		h1 := NewHandler(s1)
392		createSessionViaHTTP(t, h1, "dev-1", "sess")
393		createSessionViaHTTP(t, h1, "dev-2", "sess-rev")
394		w, _ := postJSON(t, h1, "/v1/documents/doc/crdt/ops", crdtGSetBody("dev-1",
395			crdtGSetOp("g1", "b", "a")))
396		if w.Code != http.StatusOK {
397			t.Fatal(w.Body.String())
398		}
399		w, _ = postJSON(t, h1, "/v1/documents/doc-rev/crdt/ops", crdtCounterBody("dev-2",
400			crdtCounterOp("a1", 1)))
401		if w.Code != http.StatusOK {
402			t.Fatal(w.Body.String())
403		}
404		w, _ = postJSON(t, h1, "/v1/documents/doc-rev/permissions",
405			map[string]any{"deviceId": "dev-2", "action": "revoke"})
406		if w.Code != http.StatusOK {
407			t.Fatal(w.Body.String())
408		}
409		// Read everything once before the restart; the reads must leave no trace.
410		for _, p := range []string{
411			sessionCRDTStatePath("sess", "doc"),
412			sessionCRDTStatePath("sess", "doc-empty"),
413			sessionCRDTStatePath("sess-rev", "doc-rev"),
414		} {
415			rec := httptest.NewRecorder()
416			h1.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, p, nil))
417			_, _ = io.Copy(io.Discard, rec.Body)
418		}
419		if err := s1.Close(); err != nil {
420			t.Fatal(err)
421		}
422	
423		s2, err := app.Open(path)
424		if err != nil {
425			t.Fatal(err)
426		}
427		defer func() { _ = s2.Close() }()
428		h2 := NewHandler(s2)
429	
430		read := func(p string) *httptest.ResponseRecorder {
431			rec := httptest.NewRecorder()
432			h2.ServeHTTP(rec, httptest.NewRequest(http.MethodGet, p, nil))
433			return rec
434		}
435		if rec := read(sessionCRDTStatePath("sess", "doc")); rec.Code != http.StatusOK ||
436			rec.Body.String() != `{"type":"gset","value":["a","b"]}`+"\n" {
437			t.Fatalf("state after restart = %d %q", rec.Code, rec.Body.String())
438		}
439		assertJSONErrorStatus(t, read(sessionCRDTStatePath("sess", "doc-empty")), http.StatusNotFound)
440		assertJSONErrorStatus(t, read(sessionCRDTStatePath("ghost", "doc")), http.StatusNotFound)
441		assertJSONErrorStatus(t, read(sessionCRDTStatePath("sess-rev", "doc-rev")), http.StatusForbidden)
442	}
