347		h, s := open(t)
348		registerDevice(t, h, "dev-1")
349		registerDevice(t, h, "dev-2")
350		if w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-1", crdtCounterOp("c1", 5))); w.Code != http.StatusOK {
351			t.Fatal(w.Body.String())
352		}
353		if w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-2", crdtCounterOp("d1", 3))); w.Code != http.StatusOK {
354			t.Fatal(w.Body.String())
355		}
356		reg := func(id string, version int, value string) map[string]any {
357			return crdtRegisterBody("dev-1", map[string]any{"id": id, "version": version, "value": value})
358		}
359		if w := submitCRDT(t, h, "rdoc", reg("r1", 5, "five")); w.Code != http.StatusOK {
360			t.Fatal(w.Body.String())
361		}
362		counterBefore := crdtStateBody(t, h, "cdoc")
363		registerBefore := crdtStateBody(t, h, "rdoc")
364		_ = s.Close()
365	
366		h, s = open(t)
367		defer func() { _ = s.Close() }()
368	
369		// The merged states are byte-identical after the restart.
370		if got := crdtStateBody(t, h, "cdoc"); got != counterBefore {
371			t.Fatalf("counter state after restart = %q, want %q", got, counterBefore)
372		}
373		if got := crdtStateBody(t, h, "rdoc"); got != registerBefore {
374			t.Fatalf("register state after restart = %q, want %q", got, registerBefore)
375		}
376	
377		// Idempotent replays are still idempotent.
378		w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-1", crdtCounterOp("c1", 5)))
379		if _, created := postJSONResult(t, w); created {
380			t.Fatal("counter replay after restart must be created=false")
381		}
382		w = submitCRDT(t, h, "rdoc", reg("r1", 5, "five"))
383		if _, created := postJSONResult(t, w); created {
384			t.Fatal("register replay after restart must be created=false")
385		}
386	
387		// Regressions and stalls are still 409.
388		if w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-1", crdtCounterOp("c2", 4))); w.Code != http.StatusConflict {
389			t.Fatalf("counter regression after restart = %d, want 409", w.Code)
390		}
391		if w := submitCRDT(t, h, "rdoc", reg("r2", 4, "four")); w.Code != http.StatusConflict {
392			t.Fatalf("register regression after restart = %d, want 409", w.Code)
393		}
394		if w := submitCRDT(t, h, "rdoc", reg("r3", 5, "stall")); w.Code != http.StatusConflict {
395			t.Fatalf("register stall after restart = %d, want 409", w.Code)
396		}
397	
398		// Type fixation still holds on both documents.
399		if w := submitCRDT(t, h, "cdoc", crdtGSetBody("dev-1", crdtGSetOp("g1", "x"))); w.Code != http.StatusConflict {
400			t.Fatalf("gset on counter doc after restart = %d, want 409", w.Code)
401		}
402		if w := submitCRDT(t, h, "rdoc", crdtCounterBody("dev-1", crdtCounterOp("c9", 1))); w.Code != http.StatusConflict {
403			t.Fatalf("counter on register doc after restart = %d, want 409", w.Code)
404		}
405	
406		// And every rejection left the merged states untouched.
407		if got := crdtStateBody(t, h, "cdoc"); got != counterBefore {
408			t.Fatalf("counter state after rejections = %q, want %q", got, counterBefore)
409		}
410		if got := crdtStateBody(t, h, "rdoc"); got != registerBefore {
411			t.Fatalf("register state after rejections = %q, want %q", got, registerBefore)
412		}
